('density:capture.public_domain/1', 'e4d908841e559f9bb720e3f6eda3b23f3044265ec93f2bf26ee4ba6a6cfa15f5', $s${"$id":"density:capture.public_domain/1","$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"description":"Body of a public.domain capture (tier O0): public DNS, certificate logs, IP ownership and the homepage headers of one domain.","properties":{"dmarc":{"items":{"type":"string"},"type":"array"},"dns_a":{"items":{"type":"string"},"type":"array"},"dns_aaaa":{"items":{"type":"string"},"type":"array"},"dns_caa":{"items":{"type":"string"},"type":"array"},"dns_mx":{"items":{"type":"string"},"type":"array"},"dns_ns":{"items":{"type":"string"},"type":"array"},"dns_txt":{"items":{"type":"string"},"type":"array"},"domain":{"type":"string"},"ip_owners":{"items":{"additionalProperties":false,"properties":{"as_name":{"type":["string","null"]},"asn":{"type":["string","null"]},"ip":{"type":"string"}},"required":["ip","asn","as_name"],"type":"object","x-density":{"name":"IpOwner"}},"type":"array"},"sources":{"additionalProperties":{"type":"string"},"type":"object"},"subdomains":{"items":{"type":"string"},"type":"array"},"web_header_names":{"items":{"type":"string"},"type":"array"},"web_script_hosts":{"items":{"type":"string"},"type":"array"},"web_server":{"type":["string","null"]},"web_status":{"type":["string","null"]},"www_a":{"items":{"type":"string"},"type":"array"},"www_cname":{"items":{"type":"string"},"type":"array"}},"required":["domain","dns_a","dns_aaaa","dns_mx","dns_ns","dns_txt","dns_caa","dmarc","www_a","www_cname","subdomains","ip_owners","web_server","web_status","web_header_names","web_script_hosts","sources"],"title":"PublicDomainCapture","type":"object","x-density":{"authority":"NONE","encoding":"RFC8785","oracle":"uac.acquire_domain","owner":"uacd","quirks":["web_status is a decimal string, as the oracle records it"],"route":"public.domain","table":"uac.capture_bodies"}}$s$::jsonb),
('density:core.signed_envelope/1', '5c334747d97513990d049d0f14b832834e662a67f02808351e794f450e485577', $s${"$id":"density:core.signed_envelope/1","$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"description":"What every service sends another: a payload named by its schema, its RFC 8785 digest, and an Ed25519 signature verified in Rust by the receiver. Signatures survive transport changes because they cover the digest, not the bytes on the wire.","properties":{"issued_at":{"type":"string"},"issuer_key_id":{"type":"string"},"payload":{},"payload_sha256":{"pattern":"^[0-9a-f]{64}$","type":"string"},"schema":{"pattern":"^density:[a-z0-9_.]+/[0-9]+$","type":"string"},"signature":{"pattern":"^[0-9a-f]{128}$","type":"string"}},"required":["schema","payload","payload_sha256","issuer_key_id","issued_at","signature"],"title":"SignedEnvelope","type":"object","x-density":{"authority":"NONE","encoding":"RFC8785","owner":"dc-types","wire":"gRPC density.core.v1.Envelope"}}$s$::jsonb),
('density:uac.capture_admission/1', '58d24a90b108a364d2bc97442fee1c6c0252af0eb82d44681bff10b45f05cbfc', $s${"$id":"density:uac.capture_admission/1","$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"description":"What uacd submits to admit one capture: the scope, the route, the subject, the sealed body and its summary.","properties":{"body":{"type":"object"},"route":{"type":"string"},"scope":{"format":"uuid","type":"string"},"subject":{"type":"string"},"summary":{"type":"object"}},"required":["scope","route","subject","body","summary"],"title":"CaptureAdmission","type":"object","x-density":{"authority":"NONE","encoding":"RFC8785","function":"uac.admit_capture","owner":"uacd"}}$s$::jsonb),
('density:uap.candidate_system/1', '4cbe7d4d15906c0fc02def2145aa06aaab7c41bc6438fed3cca3210ae94d882b', $s${"$id":"density:uap.candidate_system/1","$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"description":"A system seen by one or more seed ports; a candidate, never a connection (master: Connection and onboarding).","properties":{"access":{"properties":{"scope_class":{"enum":["data","sign-in only"]},"scopes":{"items":{"type":"string"},"type":"array"},"users":{"type":"integer"},"workspace_users":{"type":"integer"}},"type":["object","null"],"x-density":{"name":"AccessSummary"}},"candidate_key":{"pattern":"^[a-z0-9]+$","type":"string"},"category":{"type":["string","null"]},"independent_witnesses":{"minimum":1,"type":"integer"},"inputs":{"additionalProperties":{"type":"string"},"type":"object"},"product":{"type":"string"},"status":{"enum":["DISCOVERED","CORROBORATED"]},"witnesses":{"items":{"properties":{"basis":{"type":"string"},"determines":{"type":"string"},"evidence":{},"orbit":{"items":{"type":"string"},"type":"array"},"scope":{"type":"string"},"seed_kind":{"enum":["public_footprint","identity_catalog","code_host"]}},"required":["seed_kind","scope","evidence","determines","basis"],"type":"object","x-density":{"name":"Witness"}},"minItems":1,"type":"array"}},"required":["candidate_key","product","category","witnesses","independent_witnesses","status","access","inputs"],"title":"CandidateSystem","type":"object","x-density":{"authority":"NONE","encoding":"RFC8785","oracle":"uap.corroborate_seed_ports","owner":"uapd","table":"uap.candidate_systems"}}$s$::jsonb),
('density:uap.connection_plan/1', '550ee239328add3f755c88210c21eae7508a2cf800d07d44140d7ebb4aeb3923', $s${"$id":"density:uap.connection_plan/1","$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"description":"How a candidate system would be connected next, at the lowest tier that can answer; ranks, never authorizes.","properties":{"candidate_key":{"type":"string"},"cost":{"type":"string"},"next_step":{"type":"string"},"next_tier":{"enum":["O0","O1","O2","O3"]},"rationale":{"type":"string"},"tiers_observed":{"items":{"type":"string"},"type":"array"},"value":{"maximum":1,"minimum":0,"type":"number"},"write_path":{"enum":["None"]}},"required":["candidate_key","tiers_observed","next_tier","next_step","value","cost","write_path","rationale"],"title":"ConnectionPlan","type":"object","x-density":{"authority":"NONE","encoding":"RFC8785","oracle":"uap.corroborate_seed_ports","owner":"uapd","table":"uap.connection_plans"}}$s$::jsonb)
